import type { ChartPoint } from './types';

export interface HrZone {
  id: number;
  name: string;
  from: number;
  to: number;
  color: string;
}

export function defaultZones(maxHr: number): HrZone[] {
  return [
    { id: 1, name: 'Z1 Восстановление', from: 0, to: Math.round(maxHr * 0.6), color: '#9aa0a6' },
    {
      id: 2,
      name: 'Z2 Аэробная',
      from: Math.round(maxHr * 0.6),
      to: Math.round(maxHr * 0.7),
      color: '#3498db',
    },
    {
      id: 3,
      name: 'Z3 Темповая',
      from: Math.round(maxHr * 0.7),
      to: Math.round(maxHr * 0.8),
      color: '#2ecc71',
    },
    {
      id: 4,
      name: 'Z4 Пороговая',
      from: Math.round(maxHr * 0.8),
      to: Math.round(maxHr * 0.9),
      color: '#f39c12',
    },
    {
      id: 5,
      name: 'Z5 Максимальная',
      from: Math.round(maxHr * 0.9),
      to: Infinity,
      color: '#e74c3c',
    },
  ];
}

export function karvonenZones(maxHr: number, restHr: number): HrZone[] {
  const r = maxHr - restHr;
  const at = (p: number) => Math.round(restHr + r * p);
  return [
    { id: 1, name: 'Z1 Восстановление', from: 0, to: at(0.6), color: '#9aa0a6' },
    { id: 2, name: 'Z2 Аэробная', from: at(0.6), to: at(0.7), color: '#3498db' },
    { id: 3, name: 'Z3 Темповая', from: at(0.7), to: at(0.8), color: '#2ecc71' },
    { id: 4, name: 'Z4 Пороговая', from: at(0.8), to: at(0.9), color: '#f39c12' },
    { id: 5, name: 'Z5 Максимальная', from: at(0.9), to: Infinity, color: '#e74c3c' },
  ];
}

export function zoneOf(hr: number, zones: HrZone[]): HrZone {
  return zones.find((z) => hr >= z.from && hr < z.to) ?? zones[zones.length - 1];
}

export interface ZonedPoint extends ChartPoint {
  [key: `hrZ${number}`]: number | undefined;
}

export function addZoneSeries(points: ChartPoint[], zones: HrZone[]): ZonedPoint[] {
  const out: ZonedPoint[] = points.map((p) => {
    const copy = { ...p } as ZonedPoint;
    for (const z of zones) copy[`hrZ${z.id}`] = undefined;
    return copy;
  });

  for (let i = 0; i < out.length; i++) {
    const hr = out[i].heartRate;
    if (typeof hr !== 'number' || !Number.isFinite(hr)) continue;

    const z = zoneOf(hr, zones);
    out[i][`hrZ${z.id}`] = hr;

    if (i < out.length - 1) {
      const nhr = out[i + 1].heartRate;
      if (typeof nhr === 'number' && Number.isFinite(nhr)) {
        const nz = zoneOf(nhr, zones);
        if (nz.id !== z.id) {
          out[i][`hrZ${nz.id}`] = hr;
          out[i + 1][`hrZ${z.id}`] = nhr;
        }
      }
    }
  }
  return out;
}
