import type { MetricConfig, MetricKey } from './types';

const fmtPace = (v: number): string => {
  if (!Number.isFinite(v) || v <= 0) return '—';
  const totalSec = Math.round(v * 60);
  const m = Math.floor(totalSec / 60);
  const s = totalSec % 60;
  return `${m}:${String(s).padStart(2, '0')}`;
};

