import React, { memo, useCallback, useMemo, useRef } from 'react';

import {
  ComposedChart,
  Area,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  ResponsiveContainer,
  ReferenceArea,
  ReferenceLine,
  Tooltip,
} from 'recharts';

import { CustomTooltip } from './CustomTooltip';
import type { HrZone, ZonedPoint } from './hrZones';
import { METRICS } from './metrics';
import type { MetricKey, XMode } from './types';
import { formatMetricValue } from './utils';

const LINE_STROKE_WIDTH = 1.5;
const LINE_CURVE: 'basis' | 'monotone' | 'monotoneX' | 'natural' = 'monotoneX';
const GRAD_TOP_OPACITY = 0.45;
const GRAD_BOTTOM_OPACITY = 0.02;

/** Ширина левой оси Y — должна совпадать с YAxis width ниже */
const Y_AXIS_WIDTH = 44;
/** Правый margin графика — должен совпадать с margin.right ниже */
const MARGIN_RIGHT = 8;

export interface MetricChartProps {
  data: ZonedPoint[];
  metric: MetricKey;
  xKey: 'distance' | 'time';
  xMode: XMode;
  xTickFormatter: (v: number) => string;
  xDomain: [number, number];
  xTicks: number[];
  height?: number;
  hoverIndex: number | null;
  onHoverIndex: (idx: number | null) => void;
  /** координата X в пикселях относительно .track-stack */
  onHoverChartX: (x: number) => void;
  showXAxis?: boolean;
  zones: HrZone[];
  maxHr: number;
  average?: number;
  showAverages?: boolean;
  showZoneBackground?: boolean;
}

function MetricChartImpl({
  data,
  metric,
  xKey,
  xMode,
  xTickFormatter,
  xDomain,
  xTicks,
  height = 130,
  hoverIndex,
  onHoverIndex,
  onHoverChartX,
  showXAxis = true,
  zones,
  maxHr,
  average,
  showAverages = true,
  showZoneBackground = false,
}: MetricChartProps) {
  const m = METRICS[metric];
  const isHr = metric === 'heartRate';

  const hrDomain: [number, number] = [Math.round(maxHr * 0.45), maxHr + 5];

  const hoverX = hoverIndex != null && data[hoverIndex] ? data[hoverIndex][xKey] : null;

  const gradId = `grad-${metric}`;

  const tooltipMetrics = useMemo<MetricKey[]>(() => [metric], [metric]);

  const wrapperRef = useRef<HTMLDivElement | null>(null);

  const rafRef = useRef<number | null>(null);
  const lastIdxRef = useRef<number | null>(null);
  const lastCursorXRef = useRef<number | null>(null);

  /**
   * Ищем ближайшую точку к X-значению через бинарный поиск.
   * Данные отсортированы по xKey (distance/time монотонно возрастают).
   */
  const findNearestIndex = useCallback(
    (xValue: number): number | null => {
      if (!data.length) return null;

      let lo = 0;
      let hi = data.length - 1;
      while (hi - lo > 1) {
        const mid = (lo + hi) >> 1;
        const v = (data[mid] as any)[xKey] as number;
        if (v < xValue) lo = mid;
        else hi = mid;
      }

      const vLo = (data[lo] as any)[xKey] as number;
      const vHi = (data[hi] as any)[xKey] as number;
      return Math.abs(vLo - xValue) <= Math.abs(vHi - xValue) ? lo : hi;
    },
    [data, xKey],
  );

  const handleWrapperMouseMove = useCallback(
    (e: React.MouseEvent<HTMLDivElement>) => {
      const wrapper = wrapperRef.current;
      if (!wrapper) return;

      const rect = wrapper.getBoundingClientRect();
      const stackEl = wrapper.parentElement;
      const stackRect = stackEl?.getBoundingClientRect();

      // Область рисования (без YAxis и правого margin)
      const plotLeft = rect.left + Y_AXIS_WIDTH;
      const plotRight = rect.right - MARGIN_RIGHT;
      const plotWidth = plotRight - plotLeft;
      if (plotWidth <= 0) return;

      const xRatio = Math.max(0, Math.min(1, (e.clientX - plotLeft) / plotWidth));

      // Из доли получаем значение X в домене
      const [xMin, xMax] = xDomain;
      const xValue = xMin + (xMax - xMin) * xRatio;

      const idx = findNearestIndex(xValue);

      // Координата курсора относительно .track-stack — для CSS-оверлея
      const cursorX = stackRect ? e.clientX - stackRect.left : e.clientX - rect.left;

      const idxChanged = idx !== lastIdxRef.current;
      const xChanged = cursorX !== lastCursorXRef.current;
      if (!idxChanged && !xChanged) return;

      lastIdxRef.current = idx;
      lastCursorXRef.current = cursorX;

      if (rafRef.current != null) cancelAnimationFrame(rafRef.current);
      rafRef.current = requestAnimationFrame(() => {
        if (idx != null) onHoverIndex(idx);
        onHoverChartX(cursorX);
      });
    },
    [findNearestIndex, xDomain, onHoverIndex, onHoverChartX],
  );

  // Не сбрасываем onHoverChartX — сброс делает контейнер через onMouseLeave
  const handleWrapperMouseLeave = useCallback(() => {
    lastIdxRef.current = null;
    lastCursorXRef.current = null;
    if (rafRef.current != null) {
      cancelAnimationFrame(rafRef.current);
      rafRef.current = null;
    }
    onHoverIndex(null);
  }, [onHoverIndex]);

  return (
    <div
      className="position-relative"
      ref={wrapperRef}
      onMouseMove={handleWrapperMouseMove}
      onMouseLeave={handleWrapperMouseLeave}
    >
      <div
        className="position-absolute small fw-semibold text-muted"
        style={{ top: 6, left: 52, zIndex: 2, pointerEvents: 'none' }}
      >
        {m.label}
        {typeof average === 'number' && showAverages && (
          <span className="ms-2 fw-normal">
            ср. {formatMetricValue(metric, average)} {m.unit}
          </span>
        )}
      </div>

      <ResponsiveContainer width="100%" height={height}>
        <ComposedChart data={data} margin={{ top: 20, right: MARGIN_RIGHT, left: 0, bottom: 0 }}>
          <defs>
            {!isHr && m.gradient && (
              <linearGradient id={gradId} x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor={m.color} stopOpacity={GRAD_TOP_OPACITY} />
                <stop offset="100%" stopColor={m.color} stopOpacity={GRAD_BOTTOM_OPACITY} />
              </linearGradient>
            )}
            {isHr &&
              zones.map((z) => (
                <linearGradient
                  key={`grad-hrZ${z.id}`}
                  id={`grad-hrZ${z.id}`}
                  x1="0"
                  y1="0"
                  x2="0"
                  y2="1"
                >
                  <stop offset="0%" stopColor={z.color} stopOpacity={0.35} />
                  <stop offset="100%" stopColor={z.color} stopOpacity={0.02} />
                </linearGradient>
              ))}
          </defs>

          {isHr &&
            showZoneBackground &&
            zones.map((z) => (
              <ReferenceArea
                key={`zbg-${z.id}`}
                yAxisId="metric"
                y1={z.from}
                y2={z.to === Infinity ? maxHr + 5 : z.to}
                fill={z.color}
                fillOpacity={0.08}
                strokeOpacity={0}
              />
            ))}

          <CartesianGrid
            strokeDasharray="3 3"
            stroke="#e0e0e0"
            strokeOpacity={0.9}
            vertical={true}
            horizontal={true}
          />

          <XAxis
            dataKey={xKey}
            type="number"
            domain={xDomain}
            ticks={xTicks}
            tickFormatter={xTickFormatter}
            stroke="#888"
            fontSize={11}
            scale={xKey === 'time' ? 'time' : 'linear'}
            tickMargin={4}
            height={showXAxis ? 22 : 0}
            hide={!showXAxis}
          />

          <YAxis
            yAxisId="metric"
            orientation="left"
            stroke={m.color}
            fontSize={11}
            width={Y_AXIS_WIDTH}
            reversed={m.reversed}
            tickMargin={2}
            domain={isHr ? hrDomain : ['auto', 'auto']}
            tickFormatter={m.valueFormatter ? (v: number) => m.valueFormatter!(v) : undefined}
          />

          {/* Tooltip оставляем — Recharts сам найдёт активную точку
              для отображения карточки. Наш hoverIndex — независимый. */}
          <Tooltip
            content={<CustomTooltip xMode={xMode} activeMetrics={tooltipMetrics} zones={zones} />}
          />

          {/* Заливки */}
          {isHr &&
            zones.map((z) => (
              <Area
                key={`hr-fill-z${z.id}`}
                yAxisId="metric"
                type={LINE_CURVE}
                dataKey={`hrZ${z.id}`}
                stroke="none"
                fill={`url(#grad-hrZ${z.id})`}
                fillOpacity={1}
                dot={false}
                activeDot={false}
                isAnimationActive={false}
                connectNulls={false}
                legendType="none"
                tooltipType="none"
              />
            ))}
          {!isHr && m.gradient && (
            <Area
              yAxisId="metric"
              type={LINE_CURVE}
              dataKey={m.key}
              stroke="none"
              fill={`url(#${gradId})`}
              fillOpacity={1}
              dot={false}
              activeDot={false}
              isAnimationActive={false}
              connectNulls={false}
              legendType="none"
              tooltipType="none"
            />
          )}

          {/* Линии */}
          {isHr ? (
            zones.map((z) => (
              <Line
                key={`hr-z${z.id}`}
                yAxisId="metric"
                type={LINE_CURVE}
                dataKey={`hrZ${z.id}`}
                stroke={z.color}
                strokeWidth={LINE_STROKE_WIDTH}
                strokeLinecap="round"
                strokeLinejoin="round"
                dot={false}
                activeDot={false}
                isAnimationActive={false}
                connectNulls={false}
              />
            ))
          ) : (
            <Line
              yAxisId="metric"
              type={LINE_CURVE}
              dataKey={m.key}
              stroke={m.color}
              strokeWidth={LINE_STROKE_WIDTH}
              strokeLinecap="round"
              strokeLinejoin="round"
              dot={false}
              activeDot={false}
              isAnimationActive={false}
              connectNulls={false}
            />
          )}

          {/* Средняя */}
          {showAverages && typeof average === 'number' && (
            <ReferenceLine
              yAxisId="metric"
              y={average}
              stroke={isHr ? '#495057' : m.color}
              strokeDasharray="4 4"
              strokeWidth={1}
              strokeOpacity={0.7}
              ifOverflow="extendDomain"
            />
          )}

          {/* Невидимый ReferenceLine — чтобы Recharts подсветил активную точку
              встроенному Tooltip. Видимый курсор рисует TrackChart через CSS-оверлей. */}
          {hoverX != null && (
            <ReferenceLine
              yAxisId="metric"
              x={hoverX}
              stroke="#495057"
              strokeWidth={1}
              strokeOpacity={0}
              ifOverflow="extendDomain"
            />
          )}
        </ComposedChart>
      </ResponsiveContainer>
    </div>
  );
}

export const MetricChart = memo(MetricChartImpl);
