import { useCallback, useEffect, useMemo, useRef, useState } from 'react';

import { addZoneSeries, defaultZones } from './hrZones';
import { MetricChart } from './MetricChart';
import { METRICS, ALL_METRIC_KEYS } from './metrics';
import type { ChartPoint, GpxPoint, MetricKey, XMode } from './types';
import {
  fmtClockShort,
  formatMetricValue,
  getAvailableMetrics,
  lttb,
  toChartPoints,
} from './utils';
const MAX_POINTS = 1500;
const LTTB_THRESHOLD = 1200;

interface TrackChartProps {
  data: GpxPoint[];
  showMetrics?: MetricKey[];
  initialXMode?: XMode;
  maxHr?: number;
  showZoneBackground?: boolean;
  showAverages?: boolean;
  chartHeight?: number;
  onHoverPoint?: (point: ChartPoint | null) => void;
}

export default function TrackChart({
  data,
  showMetrics,
  initialXMode = 'distance',
  maxHr = 190,
  showZoneBackground = true,
  showAverages = true,
  chartHeight = 120,
  onHoverPoint,
}: TrackChartProps) {
  const zones = useMemo(() => defaultZones(maxHr), [maxHr]);

  const rawData = useMemo(() => toChartPoints(data), [data]);

  const [xMode, setXMode] = useState<XMode>(initialXMode);

  const xKey: 'distance' | 'time' = xMode === 'distance' ? 'distance' : 'time';

  const xTickFormatter = useCallback(
    (v: number): string => (xMode === 'distance' ? `${v.toFixed(1)} км` : fmtClockShort(v)),
    [xMode],
  );

  const baseData = useMemo(() => {
    if (rawData.length <= MAX_POINTS) return rawData;
    return lttb(
      rawData,
      LTTB_THRESHOLD,
      (d) => (xMode === 'distance' ? d.distance : d.time),
      (d) => d.altitude,
    );
  }, [rawData, xMode]);

  const chartData = useMemo(() => addZoneSeries(baseData, zones), [baseData, zones]);

  const availableMetrics = useMemo(() => getAvailableMetrics(baseData), [baseData]);

  const [activeMetrics, setActiveMetrics] = useState<MetricKey[]>(() => {
    const wanted = showMetrics ?? availableMetrics;
    return wanted.filter((k) => availableMetrics.includes(k));
  });
  const [hoverIndex, setHoverIndex] = useState<number | null>(null);
  const [cursorLeft, setCursorLeft] = useState<number | null>(null);
  const [brushRange] = useState<{
    startIndex: number;
    endIndex: number;
  } | null>(null);

  useEffect(() => {
    setActiveMetrics((prev) => prev.filter((k) => availableMetrics.includes(k)));
  }, [availableMetrics]);

  const toggleMetric = useCallback((key: MetricKey): void => {
    setActiveMetrics((prev) =>
      prev.includes(key) ? prev.filter((k) => k !== key) : [...prev, key],
    );
  }, []);

  const { visibleData, xDomain, xTicks, visibleStartIndex } = useMemo(() => {
    const start = brushRange?.startIndex ?? 0;
    const end = brushRange?.endIndex ?? chartData.length - 1;
    const visible = chartData.slice(start, end + 1);

    if (!visible.length) {
      return {
        visibleData: chartData,
        xDomain: [0, 1] as [number, number],
        xTicks: [0, 1],
        visibleStartIndex: 0,
      };
    }

    const values = visible.map((d) => d[xKey]).filter(Number.isFinite);
    const min = Math.min(...values);
    const max = Math.max(...values);
    const count = 6;
    const step = (max - min) / Math.max(1, count - 1);
    const ticks = Array.from({ length: count }, (_, i) => min + i * step);

    return {
      visibleData: visible,
      xDomain: [min, max] as [number, number],
      xTicks: ticks,
      visibleStartIndex: start,
    };
  }, [chartData, xKey, brushRange]);

  const averages = useMemo<Partial<Record<MetricKey, number>>>(() => {
    const out: Partial<Record<MetricKey, number>> = {};
    for (const key of activeMetrics) {
      const values = baseData
        .map((d) => d[key])
        .filter((v): v is number => typeof v === 'number' && Number.isFinite(v));
      if (!values.length) continue;
      out[key] = values.reduce((a, b) => a + b, 0) / values.length;
    }
    return out;
  }, [baseData, activeMetrics]);

  // --- onHoverPoint через ref + дедупликация ---
  const onHoverPointRef = useRef(onHoverPoint);
  useEffect(() => {
    onHoverPointRef.current = onHoverPoint;
  }, [onHoverPoint]);

  const lastGlobalIdxRef = useRef<number | null>(null);
  useEffect(() => {
    const cb = onHoverPointRef.current;
    if (!cb) return;

    if (hoverIndex == null) {
      if (lastGlobalIdxRef.current !== null) {
        lastGlobalIdxRef.current = null;
        cb(null);
      }
      return;
    }

    const globalIdx = visibleStartIndex + hoverIndex;
    if (globalIdx === lastGlobalIdxRef.current) return;
    lastGlobalIdxRef.current = globalIdx;
    cb(baseData[globalIdx] ?? null);
  }, [hoverIndex, visibleStartIndex, baseData]);

  // --- Троттлинг пиксельной X-координаты ---
  const cursorRafRef = useRef<number | null>(null);

  const handleHoverChartX = useCallback((x: number) => {
    if (cursorRafRef.current != null) cancelAnimationFrame(cursorRafRef.current);
    cursorRafRef.current = requestAnimationFrame(() => setCursorLeft(x));
  }, []);

  const handleHoverIndex = useCallback((idx: number | null) => {
    setHoverIndex(idx);
  }, []);

  // Сброс только при уходе со всего стека
  const handleStackMouseLeave = useCallback(() => {
    setCursorLeft(null);
    setHoverIndex(null);
  }, []);

  const orderedMetrics = ALL_METRIC_KEYS.filter((k) => activeMetrics.includes(k));

  return (
    <div className="card shadow-sm border-0">
      <div className="card-body p-2">
        {/* Верхняя панель */}
        <div className="d-flex flex-wrap align-items-center gap-2 mb-3">
          {ALL_METRIC_KEYS.filter((k) => availableMetrics.includes(k)).map((key) => {
            const m = METRICS[key];
            const active = activeMetrics.includes(key);
            const avg = averages[key];
            const avgLabel = typeof avg === 'number' ? formatMetricValue(key, avg) : '—';

            return (
              <button
                key={key}
                type="button"
                onClick={() => toggleMetric(key)}
                className={
                  'btn btn-sm d-flex align-items-center gap-2 ' +
                  (active ? 'btn-light' : 'btn-outline-secondary opacity-75')
                }
                style={{
                  borderWidth: 1,
                  borderColor: active ? m.color : 'transparent',
                  backgroundColor: active ? `${m.color}15` : undefined,
                  color: active ? '#212529' : '#adb5bd',
                }}
                aria-pressed={active}
              >
                <span
                  className="rounded-circle d-inline-block"
                  style={{
                    width: 10,
                    height: 10,
                    background: m.color,
                    opacity: active ? 1 : 0.3,
                  }}
                />
                <span className="fw-medium">{m.label}</span>
                <span className="text-muted small">
                  ср. {avgLabel} {m.unit}
                </span>
              </button>
            );
          })}

          <div className="btn-group ms-auto" role="group" aria-label="Ось X">
            {(
              [
                { id: 'distance', label: 'Расстояние' },
                { id: 'time', label: 'Время' },
              ] as const
            ).map((opt) => (
              <button
                key={opt.id}
                type="button"
                onClick={() => setXMode(opt.id)}
                className={
                  'btn btn-sm ' +
                  (xMode === opt.id ? 'btn-warning text-white' : 'btn-outline-secondary')
                }
              >
                {opt.label}
              </button>
            ))}
          </div>
        </div>

        {/* Стек графиков + единый CSS-курсор */}
        <div className="track-stack position-relative" onMouseLeave={handleStackMouseLeave}>
          {orderedMetrics.map((key, i) => (
            <MetricChart
              key={key}
              data={visibleData}
              metric={key}
              xKey={xKey}
              xMode={xMode}
              xTickFormatter={xTickFormatter}
              xDomain={xDomain}
              xTicks={xTicks}
              height={chartHeight}
              hoverIndex={hoverIndex}
              onHoverIndex={handleHoverIndex}
              onHoverChartX={handleHoverChartX}
              showXAxis={i === orderedMetrics.length - 1}
              zones={zones}
              maxHr={maxHr}
              average={averages[key]}
              showAverages={showAverages}
              showZoneBackground={showZoneBackground}
            />
          ))}

          {cursorLeft != null && (
            <div
              aria-hidden
              className="position-absolute top-0"
              style={{
                left: cursorLeft,
                width: 1,
                height: '100%',
                background: '#495057',
                opacity: 0.6,
                pointerEvents: 'none',
                willChange: 'left',
                zIndex: 999,
              }}
            />
          )}
        </div>
      </div>
    </div>
  );
}
