import { METRICS } from './metrics';
import type { ChartPoint, GpxPoint, MetricKey } from './types';

export function haversine(lat1: number, lon1: number, lat2: number, lon2: number): number {
  const R = 6371000;
  const toRad = (d: number) => (d * Math.PI) / 180;
  const dLat = toRad(lat2 - lat1);
  const dLon = toRad(lon2 - lon1);
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(a));
}

export function fmtClockShort(ts: number): string {
  const d = new Date(ts);
  return `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
}

export function fmtClockFull(ts: number): string {
  const d = new Date(ts);
  return `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(
    2,
    '0',
  )}:${String(d.getSeconds()).padStart(2, '0')}`;
}

function normalize(v: number | null | undefined, zeroIsMissing: boolean): number | undefined {
  if (v == null) return undefined;
  const n = Number(v);
  if (!Number.isFinite(n)) return undefined;
  if (zeroIsMissing && n === 0) return undefined;
  return n;
}

function computePace(data: GpxPoint[], i: number, windowSec = 10): number | undefined {
  if (i === 0) return undefined;

  const [ct, clat, clon] = data[i];
  const cTime = new Date(ct).getTime();

  let j = i - 1;
  while (j > 0 && cTime - new Date(data[j][0]).getTime() < windowSec * 1000) {
    j--;
  }
  if (cTime - new Date(data[j][0]).getTime() > windowSec * 1000 * 3) {
    return undefined;
  }

  const [pt, plat, plon] = data[j];
  const pTime = new Date(pt).getTime();
  const dtSec = (cTime - pTime) / 1000;
  if (dtSec <= 0) return undefined;

  const distKm = haversine(plat, plon, clat, clon) / 1000;
  if (distKm < 0.005) return undefined;

  const minPerKm = dtSec / 60 / distKm;
  if (minPerKm < 1.5 || minPerKm > 30) return undefined;

  return +minPerKm.toFixed(3);
}

export function toChartPoints(data: GpxPoint[]): ChartPoint[] {
  if (!data.length) return [];

  let totalDist = 0;
  const out: ChartPoint[] = [];

  for (let i = 0; i < data.length; i++) {
    const [date, lat, lon, alt, hr, temp, cad] = data[i];

    if (i > 0) {
      const [, plat, plon] = data[i - 1];
      totalDist += haversine(plat, plon, lat, lon);
    }

    const time = new Date(date).getTime();

    out.push({
      idx: i,
      time,
      distance: +(totalDist / 1000).toFixed(3),
      altitude: alt,
      latitude: lat,
      longitude: lon,
      heartRate: normalize(hr, METRICS.heartRate.zeroIsMissing ?? true),
      temperature: normalize(temp, METRICS.temperature.zeroIsMissing ?? false),
      cadence: normalize(cad, METRICS.cadence.zeroIsMissing ?? true),
      pace: computePace(data, i, 10),
    });
  }
  return out;
}

export function getAvailableMetrics(points: ChartPoint[], minCoverage = 2): MetricKey[] {
  if (!points.length) return [];

  const count = (key: MetricKey): number =>
    points.reduce((acc, p) => acc + (Number.isFinite(p[key] as number) ? 1 : 0), 0);

  return (Object.keys(METRICS) as MetricKey[]).filter((key) => {
    const cfg = METRICS[key];
    if (!cfg.optional) return true;
    return count(key) >= minCoverage;
  });
}

export function formatMetricValue(key: MetricKey, v: number): string {
  const m = METRICS[key];
  if (m.valueFormatter) return m.valueFormatter(v);
  return String(Math.round(v));
}

/** Largest-Triangle-Three-Buckets: прореживание с сохранением формы */
export function lttb<T>(
  data: T[],
  threshold: number,
  getX: (d: T) => number,
  getY: (d: T) => number,
): T[] {
  const n = data.length;
  if (threshold >= n || threshold < 3) return data;

  const sampled: T[] = [];
  const every = (n - 2) / (threshold - 2);
  let a = 0;

  sampled.push(data[0]);

  for (let i = 0; i < threshold - 2; i++) {
    const rangeStart = Math.floor((i + 1) * every) + 1;
    const rangeEnd = Math.min(Math.floor((i + 2) * every) + 1, n);

    let avgX = 0;
    let avgY = 0;
    const len = rangeEnd - rangeStart || 1;
    for (let j = rangeStart; j < rangeEnd; j++) {
      avgX += getX(data[j]);
      avgY += getY(data[j]);
    }
    avgX /= len;
    avgY /= len;

    const rangeOffs = Math.floor(i * every) + 1;
    const rangeTo = Math.floor((i + 1) * every) + 1;
    const pointAX = getX(data[a]);
    const pointAY = getY(data[a]);

    let maxArea = -1;
    let maxAreaPoint = rangeOffs;

    for (let j = rangeOffs; j < rangeTo; j++) {
      const area = Math.abs(
        (pointAX - avgX) * (getY(data[j]) - pointAY) - (pointAX - getX(data[j])) * (avgY - pointAY),
      );
      if (area > maxArea) {
        maxArea = area;
        maxAreaPoint = j;
      }
    }

    sampled.push(data[maxAreaPoint]);
    a = maxAreaPoint;
  }

  sampled.push(data[n - 1]);
  return sampled;
}
