import React from 'react';

import { zoneOf, type HrZone } from './hrZones';
import { METRICS } from './metrics';
import type { ChartPoint, MetricKey, XMode } from './types';
import { fmtClockFull, formatMetricValue } from './utils';

interface TooltipPayloadItem {
  payload?: ChartPoint;
  dataKey?: string | number;
  value?: number | string;
  name?: string;
  color?: string;
}

interface CustomTooltipProps {
  active?: boolean;
  payload?: ReadonlyArray<TooltipPayloadItem>;
  xMode: XMode;
  activeMetrics: MetricKey[];
  zones?: HrZone[];
}

export const CustomTooltip = React.memo(function CustomTooltip({
  active,
  payload,
  xMode,
  activeMetrics,
  zones,
}: CustomTooltipProps) {
  if (!active || !payload?.length) return null;

  const point = payload[0]?.payload;
  if (!point) return null;

  const header =
    xMode === 'distance'
      ? `${point.distance.toFixed(2)} км · ${fmtClockFull(point.time)}`
      : `${fmtClockFull(point.time)} · ${point.distance.toFixed(2)} км`;

  return (
    <div
      className="bg-white border rounded-3 shadow-sm px-3 py-2"
      style={{ fontFamily: 'system-ui', fontSize: 13, minWidth: 210 }}
    >
      <div className="fw-semibold mb-1">{header}</div>
      {activeMetrics.map((key) => {
        const m = METRICS[key];
        const v = point[key];
        if (typeof v !== 'number' || !Number.isFinite(v)) return null;

        const zone = key === 'heartRate' && zones ? zoneOf(v, zones) : null;
        const color = zone ? zone.color : m.color;
        const label = zone ? `${m.label} · ${zone.name.split(' ')[0]}` : m.label;

        return (
          <div key={key} className="d-flex align-items-center gap-2 text-body">
            <span
              className="rounded-circle flex-shrink-0"
              style={{ width: 8, height: 8, background: color }}
            />
            <span className="flex-grow-1">{label}</span>
            <span className="text-nowrap" style={{ fontVariantNumeric: 'tabular-nums' }}>
              {formatMetricValue(key, v)} {m.unit}
            </span>
          </div>
        );
      })}
    </div>
  );
});
